1	import Link from "next/link";
2	import { IconCheck } from "./icons";
3	import { planTip, planAudience } from "./planTips";
4	import { currentPromo, promoEndsAt, promoPriceCents } from "@/lib/promotions";
5	import { PromoBadge } from "./PromoBadge";
6	import { PromoCountdown } from "./PromoCountdown";
7	
8	export type PlanCard = {
9	  id: string;
10	  name: string;
11	  cpuCores: number;
12	  ramMB: number;
13	  diskGB: number;
14	  bandwidthTB: number;
15	  priceCents: number;
16	  storageTier: string;
17	};
18	
19	function money(cents: number) {
20	  const v = cents / 100;
21	  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
22	}
23	
24	function planFeatures(p: PlanCard): string[] {
25	  const disk = p.storageTier === "hdd" ? "HDD storage" : "NVMe SSD storage";
26	  return [
27	    `${p.cpuCores} vCPU core${p.cpuCores > 1 ? "s" : ""}`,
28	    `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM`,
29	    `${p.diskGB} GB ${disk}`,
30	    `${p.bandwidthTB} TB bandwidth`,
31	    "Full root access",
32	    "Free DDoS protection",
33	  ];
34	}
35	
36	export function PricingGrid({ plans }: { plans: PlanCard[] }) {
37	  // Highlight the middle plan (by position) as "Most popular".
38	  const popularIdx = plans.length ? Math.floor((plans.length - 1) / 2) : -1;
39	
40	  if (plans.length === 0) {
41	    return (
42	      <div className="card text-center text-slate-400">
43	        Plans are being provisioned. Please check back shortly.
44	      </div>
45	    );
46	  }
47	
48	  // Active seasonal promo (honest intro discount). The struck-through price is
49	  // the regular monthly price = the real renewal price; the discounted price is
50	  // promoPriceCents(regular) = exactly what checkout charges for the first term.
51	  const now = new Date();
52	  const promo = currentPromo(now);
53	  const promoEndsIso = promoEndsAt(now, promo).toISOString();
54	
55	  return (
56	    <div>
57	      {/* Honest promo banner: badge + real countdown + transparent renewal note. */}
58	      <div className="mb-6 flex flex-wrap items-center justify-center gap-x-3 gap-y-2 rounded-2xl border border-brand-500/25 bg-gradient-to-r from-accent-blue/10 to-brand-500/10 px-5 py-3 text-center">
59	        <PromoBadge promo={promo} />
60	        <span className="text-sm text-slate-300">
61	          <span className="font-semibold text-white">{promo.discountPercent}% off your first term</span>
62	          {" — renews at the regular price."}
63	        </span>
64	        <PromoCountdown
65	          endsAt={promoEndsIso}
66	          prefix={`${promo.name} ends in`}
67	          className="text-sm font-semibold grad-text"
68	        />
69	      </div>
70	
71	      <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
72	        {plans.map((p, i) => {
73	          const popular = i === popularIdx;
74	          const regular = p.priceCents;
75	          const first = promoPriceCents(regular, promo);
76	          return (
77	          <div
78	            key={p.id}
79	            className={`group relative flex flex-col rounded-2xl border p-6 backdrop-blur-md transition-all duration-300 hover:-translate-y-1.5 ${
80	              popular
81	                ? "border-brand-500/40 bg-navy-850/80 glow-brand"
82	                : "border-white/[0.06] bg-navy-900/70 hover:border-brand-500/30 hover:bg-navy-850/70 hover:shadow-[0_0_40px_-10px_rgb(111_71_245_/_0.4)]"
83	            }`}
84	          >
85	            {popular && (
86	              <span className="absolute -top-3 left-1/2 -translate-x-1/2 rounded-full bg-gradient-to-r from-accent-blue to-brand-500 px-3 py-1 text-[11px] font-semibold uppercase tracking-wider text-white shadow-lg">
87	                Most popular
88	              </span>
89	            )}
90	            <div className="flex items-center justify-between">
91	              <h3 className="text-base font-semibold text-white">{p.name}</h3>
92	              <span className="rounded-full border border-brand-500/30 bg-brand-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wider text-brand-300">
93	                {planAudience(p)}
94	              </span>
95	            </div>
96	            <div className="mt-3">
97	              <div className="flex items-center gap-2">
98	                <span className="text-sm text-slate-500 line-through">{money(regular)}</span>
99	                <span className="rounded-md bg-emerald-500/15 px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide text-emerald-300">
100	                  -{promo.discountPercent}%
101	                </span>
102	              </div>
103	              <div className="mt-0.5 flex items-end gap-1">
104	                <span className="text-4xl font-bold tracking-tight">{money(first)}</span>
105	                <span className="mb-1 text-sm text-slate-400">/mo</span>
106	              </div>
107	              <p className="mt-1 text-[11px] leading-snug text-slate-500">
108	                First term. Renews at {money(regular)}/mo.
109	              </p>
110	            </div>
111	            <div className="mt-4 flex items-start gap-2 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
