import { vpsTerm, vpsTermPriceCents } from "./billing-terms";
import { extraDiskCentsAt } from "./extra-disk";

/**
 * What one renewal costs — the SINGLE definition, used by every path that quotes
 * or charges one: the automatic sweep in worker/billing.ts, the saved-card path,
 * the "Renew now" button, the server page and the deploy wizard's term cards.
 *
 * WHY IT LIVES IN ITS OWN FILE. It used to sit in lib/stripe-cards.ts, which
 * imports the Stripe SDK and (transitively) nodemailer. The moment a CLIENT
 * component — the deploy wizard — needed the renewal price, that import chain
 * dragged `nodemailer/lib/dkim` into the browser bundle and the build failed with
 * "Can't resolve 'fs'". The pricing rule is pure arithmetic and has no business
 * carrying a mail transport with it, so it lives here with only the two tiny
 * modules it genuinely needs. lib/stripe-cards.ts re-exports it, so no server-side
 * caller had to change.
 *
 * The rule this file exists to enforce: there is ONE renewal formula. Two
 * incidents in one day came from a second copy — first a button that hardcoded
 * "+30 days" and the monthly price while the action charged a full term ($8.99
 * shown, $97.09 taken), then the shared quote written to fix it, which computed
 * from `plan.priceCents` and so ignored `gamePlan` and would have billed a $4.99
 * game server at its $8.99 base plan. Do not add a second formula.
 */
export type RenewalCharge = {
  months: number;
  totalCents: number;
  /** The extra-root-disk portion, which gets its own invoice line. */
  extraDiskCents: number;
  extraDiskMonthlyCents: number;
  /** Human label for the invoice / receipt ("Nebula VPS" or the game plan name). */
  label: string;
};

export type PricedServer = {
  termMonths: number;
  extraDiskGB: number;
  plan: { name: string; priceCents: number };
  gamePlan: { name: string; priceCents: number; termMonths: number } | null;
  dedicatedIp: unknown | null;
};

export function renewalCharge(
  server: PricedServer,
  prices: { ipMonthlyCents: number; extraDiskPerGbCents: number },
): RenewalCharge {
  const isGame = !!server.gamePlan;
  const months = isGame ? server.gamePlan!.termMonths : vpsTerm(server.termMonths).months;
  // Extra root disk is billed EVERY cycle at the current per-GB price. Game plans
  // are a flat all-in price and never carry the add-on lines.
  const extraDiskMonthlyCents = isGame ? 0 : extraDiskCentsAt(server.extraDiskGB, prices.extraDiskPerGbCents);
  const extraDiskCents = extraDiskMonthlyCents * months;
  const totalCents = isGame
    ? server.gamePlan!.priceCents
    : vpsTermPriceCents(server.plan.priceCents, months) +
      // Bill the IP surcharge only when the server ACTUALLY holds a dedicated IP,
      // not off the intent flag — a NAT-fallback server must never be charged for
      // an IP it never received.
      (server.dedicatedIp ? prices.ipMonthlyCents * months : 0) +
      extraDiskCents;
  return {
    months,
    totalCents,
    extraDiskCents,
    extraDiskMonthlyCents,
    label: isGame ? server.gamePlan!.name : `${server.plan.name} VPS`,
  };
}

