43	function chargedCents(monthlyCents: number, months: number, promo: Promo, addonMonthlyCents = 0): number {
44	  const regularPlanCents = vpsTermPriceCents(monthlyCents, months);
45	  return promoPriceCents(regularPlanCents, promo) + addonMonthlyCents * months;
